function interpolateColor(min: number, max: number, value?: number) {
  if (max === min || !value) return "#3b82f6";

  const normalized = (value - min) / (max - min);

  const hue = (1 - normalized) * 240;

  return `hsl(${hue}, 100%, 50%)`;
}

